#!/usr/bin/env python3
"""Generate directly browsable static pages. Standard library only."""
from pathlib import Path
from html import escape
import json
ROOT = Path(__file__).resolve().parents[1]
PAGES = {'home': ('', 'Insurance technology. Business perspective.', 'Insurance technology consulting, systems modernization, fractional leadership and software solutions for insurers, MGAs, reinsurers and brokers.'), 'services': ('services/', 'Services & capabilities', 'Practical insurance technology advisory, architecture, systems modernization, integration and fractional technology leadership.'), 'about': ('about/', 'About & insurance expertise', 'Meet EclipseIQ Technologies Inc., a Canadian insurance technology company connecting operational understanding with hands-on technology delivery.'), 'faq': ('faq/', 'Frequently asked questions', 'Answers about EclipseIQ consulting, modernization, data migration, fractional leadership and EclipseSME.'), 'contact': ('contact/', 'Start a conversation', 'Discuss your insurance technology priorities with EclipseIQ Technologies Inc.'), 'privacy': ('privacy/', 'Cookies & privacy', 'How this website handles inquiries, optional analytics and your cookie preferences.'), '404': ('404.html', 'Page not found', 'Find your way back to EclipseIQ Technologies Inc.')}
SERVICES = [
('01', 'Technology strategy & advisory', 'Make technology decisions with your insurance business in view.', 'Assess your current environment, clarify priorities and develop a practical roadmap. Connect technology investment to underwriting, operations and business objectives.', ['Technology roadmaps and vendor selection', 'Eclipse Totality Assessment™', 'Governance, security review and audit readiness']),
('02', 'Architecture & modernization', 'Move forward with a clear view of what needs to connect.', 'Design solutions around existing systems, data and operational needs. Modernize legacy platforms through planned enhancements, integration and migration.', ['Solution architecture and systems design', 'Legacy systems modernization', 'Third-party platform implementation']),
('03', 'Software, integration & data', 'Turn business requirements into working solutions.', 'Develop custom software and integrations for specialized insurance requirements. Prepare and move data with attention to quality, validation and continuity.', ['Custom software and system integration', 'Data assessment, mapping and conversion', 'Migration planning and validation']),
('04', 'Operations & workflow', 'Bring the business process into the technology conversation.', 'Review how work moves through underwriting, policy administration and operational teams. Identify manual steps, improve workflows and support the people using your systems.', ['Underwriting and policy workflow improvement', 'Process optimization and automation', 'Team development and coaching']),
('05', 'Fractional technology leadership', 'Experienced leadership, aligned to the work ahead.', 'Access executive-level technology guidance without a full-time executive appointment. Shape strategy, oversee change and support your team through complex decisions.', ['Fractional CIO and technology leadership', 'Transformation and delivery oversight', 'Vendor and investment guidance'])]
FAQ = [
('Who do you work with?', 'We work with insurers, MGAs, reinsurers, brokers, program administrators and specialty insurance organizations, from emerging businesses to established enterprises.'),
('Do you work outside Canada?', 'Yes. EclipseIQ is based in Canada and supports insurance organizations in Canada and internationally.'),
('Can you help with our existing systems?', 'Yes. We assess and modernize legacy insurance systems through planning, enhancements, integrations and data migration. The approach depends on your business priorities and existing technology landscape.'),
('Do you implement platforms other than EclipseSME?', 'Yes. We provide implementation, integration and advisory services for third-party insurance platforms, as well as our own EclipseSME platform.'),
('What is the Eclipse Totality Assessment™?', 'It is a review of your insurance technology landscape, processes, data, integrations, governance and workflows. The assessment identifies risks and opportunities and produces a prioritized roadmap for improvement.'),
('Can you support data conversion and migration?', 'Yes. We help assess, cleanse, map, transform, validate and migrate data for system implementations, upgrades and modernization projects.'),
('What does fractional technology leadership involve?', 'Fractional CIO and technology leadership can include technology strategy, transformation oversight, vendor selection and aligning technology investments with business objectives. The scope is tailored to your needs.'),
('What is EclipseSME™?', 'EclipseSME is an insurance platform developed by EclipseIQ. It supports underwriting, quoting, policy administration, renewals, endorsements, document generation and operational workflows for specialty insurers, MGAs and program administrators.'),
('Can we arrange an EclipseSME demonstration?', 'Yes. Use the contact form and choose EclipseSME demonstration so we can discuss the workflows and requirements that matter to your organization.'),
('How are pricing and timelines determined?', 'Scope, system complexity, migration needs and integration requirements shape the proposal and schedule. These are discussed before work begins; there is no one-size-fits-all implementation timeline.'),
('Do you provide custom solutions?', 'Yes. Alongside configurable EclipseSME workflows, products, business rules, forms and integrations, we provide custom development and consulting for specialized requirements.')]

def build_page(key, content):
    path, title, description = PAGES[key]
    sub = key not in ['home', '404']
    pre = '../' if sub else './'
    def link(name):
        p = PAGES[name][0]
        return pre + (p + 'index.html' if p.endswith('/') else p or 'index.html')
    nav = ''.join(f'<a href="{link(n)}"{ " aria-current=\"page\"" if n == key else ""}>{label}</a>' for n,label in [('services','Services'),('about','About & expertise')])
    nav += f'<a href="{link("home")}#eclipsesme">EclipseSME<span aria-hidden="true"> ↗</span></a><a href="{link("faq")}"{ " aria-current=\"page\"" if key == "faq" else ""}>FAQ</a><a class="nav-contact" href="{link("contact")}"{ " aria-current=\"page\"" if key == "contact" else ""}>Let’s talk <span aria-hidden="true">↗</span></a>'
    canonical = 'https://eclipseiq.ca/' + path
    if key == '404': canonical = 'https://eclipseiq.ca/404.html'
    brand = '<span class="brand-name">EclipseIQ<span class="brand-company">Technologies Inc.</span></span><small>Temporary logo placeholder</small>'
    schema = {'@context':'https://schema.org','@type':'Organization','name':'EclipseIQ Technologies Inc.','url':'https://eclipseiq.ca/','description':PAGES['home'][2]}
    html = f'''<!doctype html>
<html lang="en-CA"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{escape(title)} | EclipseIQ Technologies Inc.</title>
<meta name="description" content="{escape(description, quote=True)}"><meta name="theme-color" content="#102f46"><meta name="referrer" content="strict-origin-when-cross-origin"><link rel="canonical" href="{canonical}">
<meta property="og:type" content="website"><meta property="og:locale" content="en_CA"><meta property="og:site_name" content="EclipseIQ Technologies Inc."><meta property="og:title" content="{escape(title, quote=True)}"><meta property="og:description" content="{escape(description, quote=True)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://eclipseiq.ca/assets/social.png"><meta property="og:image:alt" content="EclipseIQ Technologies Inc. — Insurance technology with business perspective"><meta name="twitter:card" content="summary_large_image">
{'<meta name="robots" content="noindex">' if key == '404' else ''}<link rel="stylesheet" href="{pre}assets/styles.css"><script src="{pre}assets/config.js" defer></script><script src="{pre}assets/site.js" defer></script><script src="{pre}assets/consent.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head>
<body><a class="skip-link" href="#main">Skip to content</a><header class="header"><div class="container header-inner"><a class="brand" href="{link('home')}" aria-label="EclipseIQ Technologies Inc. home">{brand}</a><button class="menu-toggle" aria-expanded="false" aria-controls="navigation" hidden>Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Main navigation">{nav}</nav></div></header>
<main id="main">{content.replace('@ROOT@',pre)}</main>
<footer class="footer"><div class="container"><div class="footer-top"><a class="brand" href="{link('home')}">{brand}</a><p>Insurance knowledge.<br>Technology that moves you forward.</p><a class="text-link" href="{link('contact')}">Start a conversation <span aria-hidden="true">↗</span></a></div><div class="footer-bottom"><p>© 2026 EclipseIQ Technologies Inc. <span>Based in Canada. Working internationally.</span></p><div><a href="{link('privacy')}">Cookies & privacy</a><button class="cookie-preferences" hidden>Cookie preferences</button><a href="{link('faq')}">FAQ</a></div></div></div></footer>
<section id="cookie-banner" class="cookie-banner" aria-labelledby="cookie-title" hidden><div><h2 id="cookie-title">Your privacy, your choice.</h2><p>Optional cookies help us understand website usage. You can accept or reject them and change your choice at any time. <a href="{link('privacy')}">Cookies & privacy</a></p></div><div class="cookie-actions"><button class="button button-small" data-cookie-choice="accepted">Accept</button><button class="button button-outline button-small" data-cookie-choice="rejected">Reject</button></div></section>
</body></html>'''
    arrow = '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14"/></svg>'
    html = html.replace('↗', arrow).replace('☰', '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M3 6h18M3 12h18M3 18h18"/></svg>')
    target = ROOT / ('index.html' if key == 'home' else path if key == '404' else path+'index.html')
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_text(html)

def intro(eyebrow,title,text):
    return f'<section class="page-intro"><div class="container"><p class="eyebrow">{eyebrow}</p><h1>{title}</h1><p class="intro-copy">{text}</p></div></section>'
def cta():
    return '<section class="cta"><div class="container cta-inner"><div><p class="eyebrow">A practical next step</p><h2>What’s next for your<br>insurance technology?</h2><p>Let’s discuss where you are today and where you want to go.</p></div><a class="button button-light" href="@ROOT@contact/index.html">Start a conversation <span aria-hidden="true">↗</span></a></div></section>'

def main():
    service_preview = ''.join(f'<a class="service-row" href="@ROOT@services/index.html#service-{i}"><span class="row-number">{n}</span><div><h3>{title}</h3><p>{tag}</p></div><span class="row-arrow" aria-hidden="true">↗</span></a>' for i,(n,title,tag,desc,items) in enumerate(SERVICES))
    home = '''<section class="hero"><div class="container hero-grid"><div class="hero-copy"><p class="eyebrow"><span class="status-dot"></span> Insurance technology, with perspective</p><h1>Built on insurance.<br>Focused on<br><em>what’s next.</em></h1><p>Technology decisions shape your business. We bring insurance expertise, practical advice and hands-on delivery to help you move forward.</p><div class="hero-actions"><a class="button button-light" href="./contact/index.html">Let’s talk about your priorities <span aria-hidden="true">↗</span></a><a class="hero-secondary" href="#capabilities">Explore our capabilities <span aria-hidden="true">↓</span></a></div><p class="hero-caption">EclipseIQ Technologies Inc. / Canada</p></div><div class="systems-art" role="img" aria-label="Illustration: insurance operations connected through technology"><div class="diagram-heading"><span>THE CONNECTED INSURANCE BUSINESS</span><span aria-hidden="true">+</span></div><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="orbit orbit-three"></div><div class="diagram-core"><span>BUSINESS</span><strong>People.<br>Process.<br>Technology.</strong><span>WORKING TOGETHER</span></div><span class="diagram-label label-one">Underwriting</span><span class="diagram-label label-two">Policy operations</span><span class="diagram-label label-three">Data & systems</span><span class="diagram-label label-four">Strategy</span><div class="diagram-foot"><span>Industry understanding → Practical delivery</span><span aria-hidden="true">↗</span></div></div></div></section>
<section class="audience-strip"><div class="container"><p>Purpose-built perspective for</p><ul><li>Insurers</li><li>MGAs</li><li>Reinsurers</li><li>Brokers</li><li>Specialty insurance</li></ul></div></section>
<section class="section"><div class="container split"><div><p class="eyebrow">The EclipseIQ perspective</p><h2>Good technology starts<br>with understanding<br><span class="muted">the business.</span></h2></div><div class="prose"><p class="lead">Insurance is a connected business. Your systems should reflect that.</p><p>From underwriting and policy administration to data, integration and operational change, we connect technology decisions to how your organization actually works.</p><p>We combine executive leadership experience with hands-on design and implementation. So the conversation can move from “where do we start?” to a practical path forward.</p><a class="text-link" href="./about/index.html">About EclipseIQ <span aria-hidden="true">↗</span></a></div></div></section>
<section class="section section-tint" id="capabilities"><div class="container"><div class="section-heading"><div><p class="eyebrow">Our capabilities</p><h2>From the big picture<br>to the details that matter.</h2></div><p>Advisory, leadership and delivery.<br>Connected by insurance expertise.</p></div><div class="service-list">''' + service_preview + '''</div></div></section>
<section class="section assessment"><div class="container split"><div><p class="eyebrow">Eclipse Totality Assessment™</p><h2>A clearer view.<br>A practical roadmap.</h2><p class="intro-copy">Understand the whole picture before deciding what to change.</p><a class="text-link" href="./services/index.html#assessment">Explore the assessment <span aria-hidden="true">↗</span></a></div><div class="assessment-map"><div><span>01 / Understand</span><h3>Your operating reality</h3><p>Systems, processes, data and workflows.</p></div><div><span>02 / Evaluate</span><h3>Your risks and opportunities</h3><p>Integration, governance and operational friction.</p></div><div><span>03 / Prioritize</span><h3>Your path forward</h3><p>A roadmap aligned with business priorities.</p></div></div></div></section>
<section class="product-section" id="eclipsesme"><div class="container product-grid"><div><p class="eyebrow">Our insurance platform</p><h2>EclipseSME<span>™</span></h2><p class="product-lead">Insurance expertise.<br>Built into the platform.</p><p>Developed by EclipseIQ, EclipseSME connects underwriting, policy administration and operational workflows for specialty insurers, MGAs and program administrators.</p><a class="button button-light" href="https://eclipsesme.com/" target="_blank" rel="noopener noreferrer">Explore EclipseSME <span class="sr-only">(opens in a new tab)</span><span aria-hidden="true">↗</span></a></div><div class="product-flow"><p class="eyebrow">Supporting the policy lifecycle</p><ol><li><span>01</span> Quote & underwrite</li><li><span>02</span> Issue & administer</li><li><span>03</span> Endorse & renew</li><li><span>04</span> Connect & report</li></ol><p>A product of EclipseIQ Technologies Inc.</p></div></div></section>''' + cta()
    build_page('home',home)
    rows = ''.join(f'<article class="capability" id="service-{i}"><div><p class="eyebrow">{n} / Capability</p><h2>{title}</h2></div><div><h3>{tag}</h3><p>{desc}</p><ul class="check-list">'+''.join(f'<li>{x}</li>' for x in items)+'</ul></div></article>' for i,(n,title,tag,desc,items) in enumerate(SERVICES))
    services = intro('Services & capabilities','A business-first approach.<br><em>From strategy to delivery.</em>','Specialist insurance knowledge, backed by the ability to design, build and implement. Start with the challenge, then shape the right engagement.') + '<section class="section"><div class="container">'+rows+'</div></section>' + '''<section class="section section-tint" id="assessment"><div class="container split"><div><p class="eyebrow">Eclipse Totality Assessment™</p><h2>See the whole picture.<br>Decide what comes next.</h2></div><div class="prose"><p class="lead">A comprehensive business and technology review for insurance organizations.</p><p>We examine your technology landscape, business processes, data, integrations, governance and operational workflows to identify risk, inefficiency and opportunities.</p><p>The result is a prioritized roadmap to help align technology initiatives with your long-term objectives. Scope and deliverables are agreed around your organization’s needs.</p><a class="text-link" href="@ROOT@contact/index.html?interest=assessment">Discuss an assessment <span aria-hidden="true">↗</span></a></div></div></section><section class="section"><div class="container"><p class="eyebrow">How we approach the work</p><h2>Understand. Align. Deliver.</h2><div class="three-columns"><article><span class="step">01</span><h3>Start with your reality</h3><p>Understand business objectives, operational challenges and the systems you rely on.</p></article><article><span class="step">02</span><h3>Make the path practical</h3><p>Connect priorities to a roadmap that considers people, dependencies and implementation.</p></article><article><span class="step">03</span><h3>Work through the detail</h3><p>Bring advisory and hands-on technical work together through design, integration and change.</p></article></div></div></section>''' + cta()
    build_page('services',services)
    about = intro('About EclipseIQ','Insurance understanding.<br><em>Technology perspective.</em>','A Canadian insurance technology company connecting strategic thinking with hands-on software and systems delivery.') + '''<section class="section"><div class="container split"><div><p class="eyebrow">EclipseIQ Technologies Inc.</p><h2>The business context<br>behind the technology.</h2></div><div class="prose"><p class="lead">We work where insurance operations and technology meet.</p><p>Our experience spans executive leadership, insurance operations, technology consulting and digital transformation. We support insurers, MGAs, reinsurers, brokers and specialty insurance organizations in Canada and internationally.</p><p>Whether the work involves a technology roadmap, a legacy system, an integration or a new platform, we begin with how the business operates and what it needs to achieve.</p><p>Alongside consulting and technology leadership, we develop EclipseSME™, our insurance platform for specialty organizations.</p></div></div></section><section class="section section-tint"><div class="container"><div class="section-heading"><div><p class="eyebrow">Insurance expertise</p><h2>Context that carries<br>through to delivery.</h2></div><a class="text-link" href="@ROOT@services/index.html">Explore services ↗</a></div><div class="expertise-grid"><article><h3>Underwriting & policy operations</h3><p>Workflows, policy administration, renewals and endorsements. Technology grounded in how insurance work gets done.</p></article><article><h3>Systems & information</h3><p>Architecture, integration, data conversion and analytics. A connected view of the information your teams depend on.</p></article><article><h3>Leadership & change</h3><p>Technology strategy, governance and transformation. Practical guidance for decisions that affect teams and operations.</p></article><article><h3>Specialty insurance & reinsurance</h3><p>An understanding of the requirements of insurers, MGAs, reinsurers, brokers and program administrators.</p></article></div></div></section><section class="section"><div class="container split"><div><p class="eyebrow">How we think</p><h2>Advice should lead<br>somewhere useful.</h2></div><div class="prose"><p>We look at the whole environment before recommending change. That means understanding what works, what gets in the way and where your organization wants to go.</p><p>Our work can involve EclipseSME, third-party platforms or improvements to the systems already in place. The business requirement shapes the solution.</p><a class="text-link" href="@ROOT@faq/index.html">Common questions ↗</a></div></div></section>''' + cta()
    build_page('about',about)
    questions = ''.join(f'<details><summary>{q}<span aria-hidden="true">+</span></summary><div><p>{a}</p></div></details>' for q,a in FAQ)
    build_page('faq',intro('Frequently asked questions','A little more clarity.<br><em>Before we talk.</em>','About our services, approach and insurance platform.')+'<section class="section"><div class="container faq-layout"><aside><p class="eyebrow">Explore the details</p><p>Have a specific situation in mind?</p><a class="text-link" href="@ROOT@contact/index.html">Ask us directly ↗</a></aside><div class="faq-list">'+questions+'</div></div></section>'+cta())
    contact = intro('Start a conversation','What are you<br><em>working towards?</em>','Tell us about your organization and the technology or operational challenge you’re considering.') + '''<section class="section"><div class="container contact-grid"><aside class="contact-aside"><p class="eyebrow">Let’s find a useful starting point</p><h2>Your priorities.<br>Our next conversation.</h2><p>Discuss a project, explore fractional leadership, ask about an assessment or arrange an EclipseSME demonstration.</p><div class="contact-note"><strong>Based in Canada.<br>Working internationally.</strong><p>Please share a high-level overview. Do not include policyholder, financial or other confidential information.</p></div></aside><form id="inquiry-form" novalidate><p id="delivery-note" class="form-note">JavaScript is required for secure online inquiries. The form is not yet configured for live delivery.</p><noscript><p>Enable JavaScript to use the form. No inquiry has been sent.</p></noscript><div class="form-grid"><div><label for="name">Your name <span>(required)</span></label><input id="name" name="name" autocomplete="name" required maxlength="120"></div><div><label for="email">Work email <span>(required)</span></label><input id="email" name="email" type="email" autocomplete="email" required maxlength="254"></div><div><label for="company">Organization <span>(required)</span></label><input id="company" name="company" autocomplete="organization" required maxlength="160"></div><div><label for="company-type">Organization type</label><select id="company-type" name="company_type"><option value="">Please select</option><option>Insurer</option><option>MGA / MGU</option><option>Reinsurer</option><option>Broker</option><option>Program administrator</option><option>Other</option></select></div></div><label for="interest">How can we help? <span>(required)</span></label><select id="interest" name="interest" required><option value="">Choose a topic</option><option value="consulting">Consulting & technology strategy</option><option value="modernization">Systems modernization & integration</option><option value="leadership">Fractional technology leadership</option><option value="assessment">Eclipse Totality Assessment™</option><option value="demo">EclipseSME demonstration</option><option value="other">Something else</option></select><fieldset><legend>Preferred contact method</legend><div class="radio-options"><label><input type="radio" name="contact_method" value="Email" checked> Email</label><label><input type="radio" name="contact_method" value="Phone"> Phone call</label></div></fieldset><div><label for="phone">Phone number <span>(required for a phone call)</span></label><input id="phone" name="phone" type="tel" autocomplete="tel" maxlength="40"></div><label for="message">Tell us a little about your priorities <span>(required)</span></label><textarea id="message" name="message" rows="5" required minlength="10" maxlength="5000" aria-describedby="message-hint"></textarea><p class="field-hint" id="message-hint">A short overview is enough. Please leave out confidential information.</p><div class="honeypot" aria-hidden="true"><label for="website">Leave this field empty</label><input id="website" name="_gotcha" tabindex="-1" autocomplete="off"></div><div id="form-captcha"></div><p class="form-privacy">Your details will be used to respond to your inquiry. Read our <a href="@ROOT@privacy/index.html">Cookies & privacy</a> information.</p><button class="button" type="submit" disabled>Send inquiry <span aria-hidden="true">↗</span></button><p id="form-status" class="form-status" role="status" aria-live="polite" aria-atomic="true" tabindex="-1" hidden></p></form></div></section>'''
    build_page('contact',contact)
    privacy = intro('Cookies & privacy','Your information.<br><em>Your choices.</em>','A concise explanation of how this website handles inquiries and optional analytics.') + '''<section class="section"><div class="container legal"><p class="eyebrow">Website notice / 23 October 2026</p><h2>Contact inquiries</h2><p>When you send an inquiry, EclipseIQ Technologies Inc. uses the information you provide to respond and discuss your requirements. Only provide information you are comfortable sharing for this purpose. Do not submit sensitive personal, policyholder or confidential business information.</p><p>Once live delivery is configured, inquiries are processed through Formspree. Optional spam verification may use Google reCAPTCHA if enabled. These providers process information needed to deliver and protect the form. Review <a href="https://formspree.io/legal/privacy-policy/" target="_blank" rel="noopener noreferrer">Formspree’s privacy policy (new tab)</a> and, if verification is enabled, <a href="https://policies.google.com/privacy" target="_blank" rel="noopener noreferrer">Google’s privacy policy (new tab)</a>.</p><p>In local development, the form clearly identifies simulated submissions. They are not delivered. On a hosted site, the form remains unavailable until a valid delivery configuration is supplied.</p><h2>Essential storage</h2><p>This website remembers your analytics preference in browser storage for up to 180 days. This preference is necessary to respect your choice. If browser storage is unavailable, your choice applies to the current page only.</p><h2>Optional analytics</h2><p>Optional analytics is off until you accept. The site is prepared for Google Analytics 4, but collection remains inactive until EclipseIQ’s own Measurement ID is configured. When enabled with your consent, analytics uses the canonical page address and page title; form contents, query strings and fragments are not deliberately included in page-view data. Advertising features are disabled.</p><h2>Change or withdraw consent</h2><p>Choose Cookie preferences in the footer to accept or reject optional analytics at any time. Rejecting after acceptance disables collection and reloads the page to unload the analytics script. Accessible first-party analytics cookies are removed where the browser permits. The site cannot delete third-party or HttpOnly cookies, and withdrawal does not remove data already collected.</p><h2>Hosting and external links</h2><p>Your hosting provider may process technical request information such as IP addresses and access logs when serving this site. External websites have their own privacy practices. Links open in a new tab where indicated.</p><h2>Questions about your information</h2><p>Use the <a href="@ROOT@contact/index.html">contact form</a> for questions or requests concerning information you have shared with EclipseIQ. Please avoid including sensitive details in your initial request.</p></div></section>'''
    build_page('privacy',privacy)
    build_page('404',intro('404 / Page not found','Let’s get you<br><em>back on track.</em>','This page may have moved. Explore our services or return to the homepage.')+'<div class="container error-links"><a class="button" href="./index.html">Return home ↗</a><a class="text-link" href="./services/index.html">Explore services ↗</a></div>')
    (ROOT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join(f'  <url><loc>https://eclipseiq.ca/{path}</loc></url>\n' for k,(path,_,_) in PAGES.items() if k != '404')+'</urlset>\n')
    (ROOT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://eclipseiq.ca/sitemap.xml\n')
    print('Generated 7 pages, sitemap and robots.txt')
if __name__ == '__main__': main()
